"""Small, newly authored C exercises with Python reference oracles and concrete examples."""

EXERCISES = {
'complexity': dict(title='顺序累加数组元素', tag='线性扫描',
 prompt='实现C函数long long sum_array(const int a[], int n)，返回数组前n个元素的和。n可以为0，此时返回0；0≤n≤1000，元素绝对值不超过10^6。样例用JSON数组表示参数a，n等于数组长度。请说明时间和额外空间复杂度。',
 c='long long sum_array(const int a[], int n) {\n    long long sum = 0;\n    for (int i = 0; i < n; ++i) sum += a[i];\n    return sum;\n}',
 py='def solve(a):\n    result = 0\n    for value in a:\n        result += value\n    return result',
 tests=[([],0),([1,-2,3],2),([1000000]*3,3000000)], time='O(n)', space='O(1)',
 explanation='逐个读取元素并累加。使用long long保存累加结果，避免只用int累加时数值范围不足。循环执行n次，只使用固定数量辅助变量。'),
'linear': dict(title='统计单链表结点数', tag='链表遍历',
 prompt='单链表不带头结点，Node含int data与Node *next。实现int list_length(const Node *head)，返回实际结点数；空链表返回0，保证链表无环、长度不超过10000。样例JSON数组按顺序表示链表结点值。',
 c='typedef struct Node { int data; struct Node *next; } Node;\nint list_length(const Node *head) {\n    int length = 0;\n    for (const Node *p = head; p != 0; p = p->next) ++length;\n    return length;\n}',
 py='def solve(values):\n    count = 0\n    for _ in values:\n        count += 1\n    return count',
 tests=[([],0),([4],1),([3,1,4],3)], time='O(n)', space='O(1)',
 explanation='从首元结点沿next逐个计数，直到空指针。这里明确不带头结点，所以不额外减1；不修改任何结点。'),
'stack': dict(title='检查单一类型圆括号', tag='括号平衡',
 prompt='输入C字符串只包含圆括号(与)，可以为空。实现int valid_parens(const char *s)，合法匹配返回1，否则返回0。长度不超过10000。仅这一种括号可用一个余额计数代替显式栈；若扩展为多种括号，需同时核对种类。样例输入为JSON字符串。',
 c="int valid_parens(const char *s) {\n    int balance = 0;\n    for (; *s; ++s) {\n        if (*s == '(') ++balance;\n        else if (--balance < 0) return 0;\n    }\n    return balance == 0;\n}",
 py="def solve(s):\n    balance = 0\n    for ch in s:\n        balance += 1 if ch == '(' else -1\n        if balance < 0:\n            return 0\n    return int(balance == 0)",
 tests=[('',1),('(())()',1),('())(',0),('(()',0)], time='O(n)', space='O(1)',
 explanation='左括号使余额加1，右括号减1。任意前缀余额为负立即失败，结束时余额必须恰为0。只有单一括号类型时，计数才足以代替栈保存种类信息。'),
'strings': dict(title='原地逆置一维数组', tag='双指针逆置',
 prompt='实现void reverse_array(int a[], int n)，原地把n个整数逆序。n可以为0；不要申请与n成正比的额外数组。样例输入、输出均用JSON数组表示。',
 c='void reverse_array(int a[], int n) {\n    int left = 0, right = n - 1;\n    while (left < right) {\n        int temp = a[left];\n        a[left++] = a[right];\n        a[right--] = temp;\n    }\n}',
 py='def solve(values):\n    a = list(values)\n    left, right = 0, len(a) - 1\n    while left < right:\n        a[left], a[right] = a[right], a[left]\n        left += 1\n        right -= 1\n    return a',
 tests=[([],[]),([1],[1]),([1,2,3,4],[4,3,2,1])], time='O(n)', space='O(1)（C原地实现）',
 explanation='左右指针向中间靠拢并交换。每轮确认两端位置，最多交换⌊n/2⌋次；n=0时right=-1，循环不会执行。Python参考函数复制输入只是为了方便展示输出。'),
'trees': dict(title='递归求二叉树层数', tag='二叉树高度',
 prompt='按结点层数定义高度：空树为0，单结点树为1。实现int tree_height(const TreeNode *root)。树无环、结点数不超过1000，允许为空；需说明递归空间与树高的关系。样例用[value,left,right]表示结点，用null表示空树。',
 c='typedef struct TreeNode {\n    int data; struct TreeNode *left, *right;\n} TreeNode;\nint tree_height(const TreeNode *root) {\n    if (root == 0) return 0;\n    int left = tree_height(root->left);\n    int right = tree_height(root->right);\n    return 1 + (left > right ? left : right);\n}',
 py='def solve(root):\n    if root is None:\n        return 0\n    return 1 + max(solve(root[1]), solve(root[2]))',
 tests=[(None,0),([1,None,None],1),([1,[2,[3,None,None],None],None],3)], time='O(n)', space='O(h)，h为树高',
 explanation='空树返回0，非空树高度为1加左右子树高度的较大值。每个结点访问一次；递归最大深度为树高，退化链最坏占O(n)调用栈空间。'),
'heap': dict(title='判断数组是否满足小根堆', tag='小根堆检验',
 prompt='数组从0编号。实现int is_min_heap(const int a[], int n)，若每个父结点都不大于其存在的孩子则返回1，否则返回0。允许相等元素，空数组也视为满足堆序。样例为JSON数组；只检查堆序，不要求数组有序。',
 c='int is_min_heap(const int a[], int n) {\n    for (int i = 1; i < n; ++i) {\n        if (a[(i - 1) / 2] > a[i]) return 0;\n    }\n    return 1;\n}',
 py='def solve(a):\n    for i in range(1, len(a)):\n        if a[(i - 1) // 2] > a[i]:\n            return 0\n    return 1',
 tests=[([],1),([1,3,2,7],1),([2,1],0),([2,2,2],1)], time='O(n)', space='O(1)',
 explanation='对每个非根结点i检查其父下标(i-1)/2。只要一条父子关系违反堆序就失败。无需把兄弟排序，也不能误要求整个数组递增。'),
'graphs': dict(title='邻接矩阵计算顶点的度', tag='邻接矩阵扫描',
 prompt='给定不含自环的简单无向图，采用0/1邻接矩阵存储。实现int vertex_degree(int n, const int a[][100], int v)，统计顶点v的度。1≤n≤100，0≤v<n。样例JSON对象matrix给出有效n×n区域，vertex给出v。',
 c='int vertex_degree(int n, const int a[][100], int v) {\n    int degree = 0;\n    for (int j = 0; j < n; ++j) degree += a[v][j];\n    return degree;\n}',
 py='def solve(value):\n    row = value["matrix"][value["vertex"]]\n    degree = 0\n    for adjacent in row:\n        degree += adjacent\n    return degree',
 tests=[({'matrix':[[0]],'vertex':0},0),({'matrix':[[0,1,1],[1,0,0],[1,0,0]],'vertex':0},2),({'matrix':[[0,1],[1,0]],'vertex':1},1)], time='O(n)', space='O(1)',
 explanation='简单无向图无自环且使用0/1矩阵，第v行每个1代表一条关联边，行和就是度。对于允许自环或多重边的图，必须重新说明计数约定。'),
'search': dict(title='迭代二分查找', tag='二分边界维护',
 prompt='数组严格递增，实现int binary_search(const int a[], int n, int target)，找到返回下标，找不到返回-1。n允许为0。使用闭区间[left,right]，请保证不发生死循环。样例为含values和target的JSON对象。',
 c='int binary_search(const int a[], int n, int target) {\n    int left = 0, right = n - 1;\n    while (left <= right) {\n        int mid = left + (right - left) / 2;\n        if (a[mid] == target) return mid;\n        if (a[mid] < target) left = mid + 1;\n        else right = mid - 1;\n    }\n    return -1;\n}',
 py='def solve(value):\n    a, target = value["values"], value["target"]\n    left, right = 0, len(a) - 1\n    while left <= right:\n        mid = left + (right - left) // 2\n        if a[mid] == target:\n            return mid\n        if a[mid] < target:\n            left = mid + 1\n        else:\n            right = mid - 1\n    return -1',
 tests=[({'values':[],'target':1},-1),({'values':[1,3,5,8],'target':5},2),({'values':[1,3,5,8],'target':4},-1),({'values':[2],'target':2},0)], time='O(log n)', space='O(1)',
 explanation='每轮比较后排除mid及不可能包含目标的一半区间，用mid+1或mid-1保证区间严格缩小。空数组right=-1，直接返回-1。'),
'sorting': dict(title='实现稳定的直接插入排序', tag='插入排序实现',
 prompt='实现void insertion_sort(int a[], int n)，把整数数组原地升序排列。允许空数组与重复值。插入时只移动严格大于key的元素，以便推广到记录排序时保持稳定。样例为JSON数组。',
 c='void insertion_sort(int a[], int n) {\n    for (int i = 1; i < n; ++i) {\n        int key = a[i], j = i - 1;\n        while (j >= 0 && a[j] > key) {\n            a[j + 1] = a[j];\n            --j;\n        }\n        a[j + 1] = key;\n    }\n}',
 py='def solve(values):\n    a = list(values)\n    for i in range(1, len(a)):\n        key, j = a[i], i - 1\n        while j >= 0 and a[j] > key:\n            a[j + 1] = a[j]\n            j -= 1\n        a[j + 1] = key\n    return a',
 tests=[([],[]),([3,1,2],[1,2,3]),([2,2,1],[1,2,2]),([1],[1])], time='最坏O(n²)，已有序时O(n)', space='O(1)（C原地实现）',
 explanation='每轮把a[i]插入已排序前缀。循环条件先判断j≥0再读取a[j]，避免越界；只移动严格更大的元素，相等记录不会互相越过。'),
'design': dict(title='有序数组原地去重', tag='双指针去重实现',
 prompt='数组非递减有序，实现int unique_sorted(int a[], int n)，原地保留每个值的一次出现，返回新长度。有效结果位于数组前缀，前缀外内容不作要求。n可以为0。样例输出仅展示有效前缀。',
 c='int unique_sorted(int a[], int n) {\n    if (n == 0) return 0;\n    int write = 1;\n    for (int read = 1; read < n; ++read) {\n        if (a[read] != a[write - 1]) a[write++] = a[read];\n    }\n    return write;\n}',
 py='def solve(values):\n    a = list(values)\n    if not a:\n        return []\n    write = 1\n    for read in range(1, len(a)):\n        if a[read] != a[write - 1]:\n            a[write] = a[read]\n            write += 1\n    return a[:write]',
 tests=[([],[]),([1,1,2,2,3],[1,2,3]),([4,4,4],[4]),([-2,0,3],[-2,0,3])], time='O(n)', space='O(1)（C原地实现）',
 explanation='读指针遍历全部元素，写指针维护不含重复值的有效前缀。只有新值与前缀末尾不同才写入，避免反复删除搬移；必须先处理n=0。'),
}
